  "records": [
    {
      "id": "SG25-6ca7ea2feefc",
      "source_scopes": [
        {
          "sid": "s001",
          "scope_zh": "保持某状态、性质、位置或所有物，使继续存在",
          "recommended_pos": "动词",
          "required_context": "宾语为状态、属性、位置或所有物；也可接形容词/名词作补语",
          "evidence_ids": [
            "wn31:v:02415305",
            "wn31:v:02687605"
          ],
          "uncertainty": "原文'保持'可涵盖多种维持类用法，上述证据均为及物/使动用法，未覆盖不及物持续义（该义归入s004）"
        },
        {
          "sid": "s002",
          "scope_zh": "保管、照看或存放物品/场所",
          "recommended_pos": "动词",
          "required_context": "宾语为具体物品、场所或需照看的事物",
          "evidence_ids": [
            "wn31:v:02207710",
            "wn31:v:02208626",
            "wn31:v:02208876"
          ],
          "uncertainty": "证据02208626含储存食物以防腐的意味，中文'保管'通常不强调防腐；未采用照看人的用法，因源义限于物品/场所"
        },
        {
          "sid": "s003",
          "scope_zh": "饲养动物（家禽、蜜蜂等）",
          "recommended_pos": "动词",
          "required_context": "宾语为动物",
          "evidence_ids": [
            "wn31:v:02658111"
          ],
          "uncertainty": "证据仅示例家禽/蜜蜂，未明确所有动物；中文'饲养'可适用于各类动物，可能范围一致，但证据不足"
        },
        {
          "sid": "s004",
          "scope_zh": "继续某活动或状态，常接动名词或持续表达",
          "recommended_pos": "动词",
          "required_context": "后接活动或状态，常伴随持续性表达",
          "evidence_ids": [
            "wn31:v:02690747"
          ],
          "uncertainty": "不及物持续义与s001的及物维持义有交叉，此处按源'继续'取持续进行义；未覆盖使动'使保持'，由s001处理"
        }
      ],
      "proposed_core": [
        "动词：保持（使状态、性质、位置或所有物继续存在）",
        "动词：保管（照看、存放或负责某物/场所）",
        "动词：饲养（喂养并管理动物）",
        "动词：继续（持续进行某活动或保持某状态）"
      ],
      "deferred_source_ids": [],
      "deferral_reason": "",
      "note": "全部为AI提案，未经人工签审；名词性义项（如生活费用、城堡主楼）及其他动词义项（如阻止、遵守、提供食宿等）未纳入核心，因源词性为动词且原文未列出。"
    },
    {
      "id": "SG25-e2411f906450",
      "source_scopes": [
        {
          "sid": "s001",
          "scope_zh": "具有权力、势力，能影响他人或局势",
          "recommended_pos": "形容词",
          "required_context": "描述人、组织等具有权势的主体",
          "evidence_ids": [
            "wn31:a:01835852"
          ],
          "uncertainty": "证据中'influence or power'合并，未单独区分势力与一般影响；源'有势力的'可能侧重权力，但证据无法验证该侧重"
        },
        {
          "sid": "s002",
          "scope_zh": "具有影响力，能产生效果或改变",
          "recommended_pos": "形容词",
          "required_context": "描述人或事物对他人/事件产生影响",
          "evidence_ids": [
            "wn31:a:01835852"
          ],
          "uncertainty": "与s001共用同一证据，边界模糊；证据中示例包括报纸和领导力，既涵盖有势力也有影响，不能确定是否区分"
        }
      ],
      "proposed_core": [
        "形容词：有势力的（拥有权力或势力，能左右他人）",
        "形容词：有影响的（具有影响力或效果）"
      ],
      "deferred_source_ids": [],
      "deferral_reason": "",
      "note": "整条源词性为形容词，仅有一个英文形容词证据，两个中文义项近义；未增加其他词性义项。"
    }
  ]
}
